-- Name: v_bill_summary; Type: VIEW; Schema: hc; Owner: postgres
--

CREATE VIEW hc.v_bill_summary AS
 SELECT b.billing_id,
    b.appointment_id,
    b.amount AS billed,
    b.status AS billing_status,
    py.amount_paid,
    py.method AS payment_method,
    (b.amount - COALESCE(py.amount_paid, (0)::numeric)) AS outstanding,
    c.provider AS insurer,
    c.claim_amount,
    c.status AS claim_status
   FROM ((hc.billing b
     LEFT JOIN hc.payments py ON (((py.billing_id)::text = (b.billing_id)::text)))
     LEFT JOIN hc.insurance_claims c ON (((c.billing_id)::text = (b.billing_id)::text)));


ALTER VIEW hc.v_bill_summary OWNER TO postgres;

